"""Stream a large CSV file, validate required columns, normalize timestamps
to UTC, and aggregate totals by account without loading all rows into memory.
"""

from __future__ import annotations

import csv
import io
from dataclasses import dataclass, field
from datetime import datetime, timezone
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Any, Iterable, Iterator, Mapping, Sequence, TextIO, Union

CSVSource = Union[str, Path, TextIO, Iterable[str]]


@dataclass(frozen=True)
class CsvConfig:
    """Configuration describing the expected CSV schema."""

    required_columns: Sequence[str] = ("account_id", "amount", "timestamp")
    account_column: str = "account_id"
    amount_column: str = "amount"
    timestamp_column: str = "timestamp"
    timestamp_formats: Sequence[str] = (
        "%Y-%m-%dT%H:%M:%S%z",      # ISO 8601 with offset
        "%Y-%m-%d %H:%M:%S%z",
        "%Y-%m-%dT%H:%M:%S",        # naive -> assume UTC
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d",
    )
    default_tz: timezone = timezone.utc
    delimiter: str = ","


@dataclass(frozen=True)
class RowError:
    """A validation failure tied to a specific row (1-based, header = row 1)."""

    line_number: int
    column: str
    value: str
    message: str


@dataclass(frozen=True)
class AccountTotal:
    """Aggregated result for a single account."""

    account_id: str
    total: Decimal
    row_count: int
    first_seen_utc: datetime
    last_seen_utc: datetime


@dataclass
class AggregationResult:
    """Final output of a streaming aggregation run."""

    totals: dict[str, AccountTotal] = field(default_factory=dict)
    errors: list[RowError] = field(default_factory=list)
    rows_processed: int = 0

    @property
    def ok(self) -> bool:
        return not self.errors


def _open_source(source: CSVSource) -> tuple[TextIO, bool]:
    """Return a text stream and whether the caller owns closing it."""
    if isinstance(source, (str, Path)):
        return open(source, "r", encoding="utf-8", newline=""), True
    if hasattr(source, "read") or isinstance(source, Iterable):
        return source if hasattr(source, "read") else io.StringIO("".join(source)), False
    raise TypeError(f"Unsupported CSV source: {type(source)!r}")


def _parse_timestamp(raw: str, config: CsvConfig) -> datetime:
    """Parse a timestamp string and normalize it to UTC."""
    value = raw.strip()
    last_error: ValueError | None = None
    for fmt in config.timestamp_formats:
        try:
            parsed = datetime.strptime(value, fmt)
        except ValueError as exc:
            last_error = exc
            continue
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=config.default_tz)
        return parsed.astimezone(timezone.utc)
    raise ValueError(f"Unrecognized timestamp format: {raw!r}") from last_error


def _parse_amount(raw: str) -> Decimal:
    """Parse a decimal amount, rejecting NaN/Infinity."""
    value = Decimal(raw.strip())
    if not value.is_finite():
        raise ValueError(f"Non-finite amount: {raw!r}")
    return value


def validate_header(
    reader: csv.DictReader[str],
    config: CsvConfig,
) -> Iterator[str]:
    """Yield names of missing required columns."""
    header = reader.fieldnames or []
    for column in config.required_columns:
        if column not in header:
            yield column


def stream_rows(
    source: CSVSource,
    config: CsvConfig | None = None,
) -> Iterator[tuple[int, Mapping[str, str]]]:
    """Yield (line_number, row) pairs lazily; line numbers are 1-based."""
    cfg = config or CsvConfig()
    stream, should_close = _open_source(source)
    try:
        reader = csv.DictReader(stream, delimiter=cfg.delimiter)
        for line_number, row in enumerate(reader, start=2):
            yield line_number, row
    finally:
        if should_close:
            stream.close()


def aggregate(
    source: CSVSource,
    config: CsvConfig | None = None,
    *,
    max_errors: int = 100,
) -> AggregationResult:
    """Stream the CSV, validate each row, and aggregate totals by account.

    Rows that fail validation are recorded in ``result.errors`` and skipped;
    aggregation continues. Raises ``ValueError`` if required columns are
    missing from the header or if ``max_errors`` is exceeded.
    """
    cfg = config or CsvConfig()
    result = AggregationResult()
    stream, should_close = _open_source(source)

    try:
        reader = csv.DictReader(stream, delimiter=cfg.delimiter)
        missing = list(validate_header(reader, cfg))
        if missing:
            raise ValueError(f"Missing required columns: {', '.join(missing)}")

        for line_number, row in stream_rows_from_reader(reader, cfg):
            result.rows_processed += 1
            error = _process_row(line_number, row, cfg, result)
            if error is not None:
